    de: { q: ['Klimatherapie', 'Terrainkur', 'Wald'], a: 'Verordnete Spaziergänge auf abgestuften Waldwegen. Saubere, phytonzidreiche Luft. 630 m Höhe. Klimakurort seit 2023.' },
